#include "edudb.hpp"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <future>
#include <iostream>
#include <thread>
using namespace edudb;namespace fs=std::filesystem;using namespace std::chrono_literals;
namespace {
void check(bool yes,const std::string& message){if(!yes)throw std::runtime_error(message);}
json sql(Engine& db,const std::string& s,const std::string& text){auto j=db.execute(s,text);check(j.value("ok",false),text+": "+j.dump());return j;}
json actual_wait(Engine& db,const std::string& prefix){auto deadline=std::chrono::steady_clock::now()+2s;while(std::chrono::steady_clock::now()<deadline){auto d=db.diagnostics();if(!d["waits"].empty())for(const auto& q:d["queues"])if(q["resource"].get<std::string>().rfind(prefix,0)==0)return {{"waits",d["waits"]},{"queues",d["queues"]},{"locks",d["locks"]}};std::this_thread::sleep_for(1ms);}throw std::runtime_error("actual wait-graph barrier not observed: "+prefix);}
StorageOptions options(){StorageOptions o;o.recovery_mode="ARIES_LOGICAL";return o;}
void seed(const fs::path& root){Engine db(root.u8string(),2,32u*1024u*1024u,options());auto s=db.open_session();sql(db,s,"CREATE TABLE t(id INTEGER PRIMARY KEY,v VARCHAR(80))");sql(db,s,"INSERT INTO t VALUES(1,'原始一'),(2,'原始二')");db.checkpoint();}
json rows(Engine& db,const std::string& s){return sql(db,s,"SELECT id,v FROM t ORDER BY id")["rows"];}
json snapshot(const fs::path& root){Engine db(root.u8string(),2);auto s=db.open_session();auto result=rows(db,s);auto verified=sql(db,s,"VERIFY");check(verified["verification"]["ok"],"native logical VERIFY");return {{"status","PASS"},{"rows",result},{"diagnostics",db.diagnostics()}};}
void same_page(Engine& db,const std::string& a,const std::string& b){
 sql(db,a,"BEGIN");auto first=sql(db,a,"UPDATE t SET v='甲未提交' WHERE id=1");check(first["locking"]["effective"]=="RECORD","first SQL did not actually choose record/range locking: "+first.dump());
 sql(db,b,"BEGIN");auto second=sql(db,b,"UPDATE t SET v='乙已提交' WHERE id=2");check(second["locking"]["effective"]=="RECORD","second SQL did not choose record/range locking");sql(db,b,"COMMIT");
}
json units(const fs::path& root){json checks=json::array();
 {auto dir=root/"same-page";seed(dir);Engine db(dir.u8string(),2);auto a=db.open_session(),b=db.open_session();same_page(db,a,b);auto before=db.diagnostics();check(before["storage"]["transactions"]["page_version_graph"]["disabled"],"logical page graph falsely claims committed CSN snapshots");sql(db,a,"ROLLBACK");check(rows(db,b)==json::array({json::array({1,"原始一"}),json::array({2,"乙已提交"})}),"old page undo erased another key's commit");auto verify=sql(db,b,"VERIFY");check(verify["verification"]["ok"],"same-page rollback VERIFY");auto logs=sql(db,b,"SHOW WAL RECORDS")["diagnostic"];check(logs["mode"]=="ARIES_LOGICAL","WAL mode mislabeled");bool logical_clr=false;for(const auto& record:logs["logical_records"]["records"])if(record["type"]=="LOGICAL_CLR"){logical_clr=true;check(record["undo_next_lsn"].get<std::uint64_t>()<record["lsn"].get<std::uint64_t>(),"logical CLR UndoNext is invalid");}check(logical_clr,"SQL WAL diagnostic omitted real logical CLR");checks.push_back({{"case","real_SQL_record_locks_same_page_other_key_commit_survives_logical_rollback"},{"status","PASS"},{"before_rollback",before}});}
 {auto dir=root/"savepoint";seed(dir);Engine db(dir.u8string(),2);auto s=db.open_session();sql(db,s,"BEGIN");sql(db,s,"SAVEPOINT zero");sql(db,s,"INSERT INTO t VALUES(3,'首写前保存点')");sql(db,s,"ROLLBACK TO zero");sql(db,s,"UPDATE t SET v='保留' WHERE id=1");sql(db,s,"SAVEPOINT keep");sql(db,s,"DELETE FROM t WHERE id=2");sql(db,s,"INSERT INTO t VALUES(3,'将撤销')");sql(db,s,"ROLLBACK TO keep");sql(db,s,"COMMIT");check(rows(db,s)==json::array({json::array({1,"保留"}),json::array({2,"原始二"})}),"logical savepoint inverse insert/delete");check(sql(db,s,"VERIFY")["verification"]["ok"],"savepoint VERIFY");checks.push_back({{"case","savepoint_before_first_write_and_logical_inverse_preserve_stable_LID"},{"status","PASS"}});}
 {auto dir=root/"resource";seed(dir);Engine db(dir.u8string(),2);auto s=db.open_session();sql(db,s,"BEGIN");for(int i=0;i<3;++i)sql(db,s,"UPDATE t SET v='步骤"+std::to_string(i)+"' WHERE id=1");auto denied=db.execute(s,"UPDATE t SET v='不得执行' WHERE id=1");check(!denied.value("ok",true)&&denied["error"]["code"]=="LOGICAL_OPERATION_LIMIT","uncompensated operation budget was not enforced");sql(db,s,"ROLLBACK");check(rows(db,s)==json::array({json::array({1,"原始一"}),json::array({2,"原始二"})}),"budget-rejected transaction not completely inverse-rolled-back");checks.push_back({{"case","three_operation_credit_limit_before_write_and_safe_whole_rollback"},{"status","PASS"}});}
 {auto dir=root/"key-wait";seed(dir);Engine db(dir.u8string(),2);auto a=db.open_session(),b=db.open_session();sql(db,a,"BEGIN");sql(db,a,"UPDATE t SET v='未提交不可读' WHERE id=1");auto future=std::async(std::launch::async,[&]{return db.execute(b,"SELECT v FROM t WHERE id=1");});auto barrier=actual_wait(db,"range:");check(future.wait_for(0ms)==std::future_status::timeout,"observed key waiter returned before rollback");sql(db,a,"ROLLBACK");check(future.wait_for(2s)==std::future_status::ready,"key wait did not wake after real inverse rollback");auto result=future.get();check(result.value("ok",false)&&result["rows"]==json::array({json::array({"原始一"})}),"waiter saw wrong post-undo value");checks.push_back({{"case","outer_key_lock_held_through_inverse_and_waiter_reads_after_rollback"},{"status","PASS"},{"actual_wait_barrier",barrier}});}
 {auto dir=root/"read-only-and-errors";seed(dir);Engine db(dir.u8string(),2);auto s=db.open_session();sql(db,s,"SET TRANSACTION READ ONLY");auto readonly=db.execute(s,"INSERT INTO t VALUES(3,'拒绝只读写')");check(!readonly.value("ok",true)&&readonly["error"]["code"]=="READ_ONLY_TRANSACTION","read-only SQL reached a physical mini-commit");sql(db,s,"BEGIN");sql(db,s,"SAVEPOINT valid");auto missing=db.execute(s,"ROLLBACK TO absent");check(!missing.value("ok",true)&&missing["error"]["code"]=="SAVEPOINT_NOT_FOUND"&&!db.diagnostics()["storage"]["recovery_required"].get<bool>(),"missing savepoint poisoned whole storage");sql(db,s,"ROLLBACK");check(rows(db,s).size()==2,"read-only/invalid savepoint changed data");checks.push_back({{"case","read_only_early_rejection_and_missing_savepoint_without_global_failstop"},{"status","PASS"}});}
 {auto dir=root/"slot-reuse";seed(dir);Engine db(dir.u8string(),2);auto a=db.open_session(),b=db.open_session();sql(db,a,"BEGIN");sql(db,a,"DELETE FROM t WHERE id=1");sql(db,b,"INSERT INTO t VALUES(3,'复用旧槽')");auto before=sql(db,a,"INSPECT TABLE t")["inspection"];bool reused=false;for(const auto& page:before["structure"]["pages"])for(const auto& row:page["rows"])if(row["record"]["row"][0]==3)reused=row["slot"]==0&&row["generation"]==2&&row["record"]["id"]==3;check(reused,"fixture did not actually reuse deleted row slot");sql(db,a,"ROLLBACK");check(rows(db,b)==json::array({json::array({1,"原始一"}),json::array({2,"原始二"}),json::array({3,"复用旧槽"})}),"inverse INSERT overwrote committed reused slot");auto after=sql(db,b,"INSPECT TABLE t")["inspection"];bool kept=false,restored=false;for(const auto& page:after["structure"]["pages"])for(const auto& row:page["rows"]){if(row["record"]["row"][0]==3)kept=row["slot"]==0&&row["generation"]==2&&row["record"]["id"]==3;if(row["record"]["row"][0]==1)restored=row["record"]["id"]==1;}check(kept&&restored,"stable LID or newer generation lost during logical inverse");check(sql(db,b,"VERIFY")["verification"]["ok"],"slot reuse VERIFY");checks.push_back({{"case","committed_slot_reuse_survives_inverse_insert_with_original_LID"},{"status","PASS"},{"before",before},{"after",after}});}
 {auto dir=root/"SMO";seed(dir);Engine db(dir.u8string(),2);auto a=db.open_session(),b=db.open_session();sql(db,b,"INSERT INTO t VALUES(3,'第三行')");sql(db,b,"CREATE INDEX tiny ON t(id) WITH(max_keys=3)");sql(db,a,"BEGIN");sql(db,a,"INSERT INTO t VALUES(4,'未提交分裂')");sql(db,b,"UPDATE t SET v='乙跨分裂提交' WHERE id=2");sql(db,a,"ROLLBACK");auto preserved=sql(db,b,"INSPECT TABLE t INDEX tiny")["inspection"];check(preserved["structure"]["descriptor"]["stats"].value("splits",std::uint64_t(0))>0,"logical inverse reset already completed split history");sql(db,b,"DELETE FROM t WHERE id=3");auto merged=sql(db,b,"INSPECT TABLE t INDEX tiny")["inspection"];check(merged["structure"]["descriptor"]["stats"].value("merges",std::uint64_t(0))>0,"real SQL did not merge split tree");check(rows(db,b)==json::array({json::array({1,"原始一"}),json::array({2,"乙跨分裂提交"})}),"SMO/inverse corrupted another committed key");check(sql(db,b,"VERIFY")["verification"]["ok"],"SMO VERIFY");checks.push_back({{"case","real_SQL_split_retained_by_system_mini_transaction_and_new_logical_delete_merge"},{"status","PASS"},{"after_inverse",preserved},{"after_merge",merged}});}
 {auto dir=root/"wound-idle";seed(dir);Engine db(dir.u8string(),2);auto older=db.open_session(),younger=db.open_session();sql(db,older,"SET LOCK POLICY WOUND_WAIT");sql(db,older,"BEGIN");sql(db,younger,"BEGIN");sql(db,younger,"UPDATE t SET v='年轻未提交' WHERE id=1");auto wait=std::async(std::launch::async,[&]{return db.execute(older,"UPDATE t SET v='年长提交' WHERE id=1");});check(wait.wait_for(2s)==std::future_status::ready,"idle wound victim did not promptly inverse-rollback");auto updated=wait.get();check(updated.value("ok",false),"older requester failed after wound: "+updated.dump());sql(db,older,"COMMIT");sql(db,younger,"ROLLBACK");check(rows(db,older)[0][1]=="年长提交"&&!db.diagnostics()["storage"]["recovery_required"].get<bool>(),"wounded victim inverse ran after the new commit");checks.push_back({{"case","idle_wound_victim_keeps_key_until_background_real_inverse_finishes"},{"status","PASS"}});}
 {auto dir=root/"deadlock";seed(dir);Engine db(dir.u8string(),2);auto a=db.open_session(),b=db.open_session();sql(db,a,"BEGIN");sql(db,b,"BEGIN");sql(db,a,"UPDATE t SET v='甲一' WHERE id=1");sql(db,b,"UPDATE t SET v='乙二未提交' WHERE id=2");auto wait=std::async(std::launch::async,[&]{return db.execute(a,"UPDATE t SET v='甲二' WHERE id=2");});auto barrier=actual_wait(db,"range:");check(wait.wait_for(0ms)==std::future_status::timeout,"observed deadlock first waiter returned early");auto victim=db.execute(b,"UPDATE t SET v='乙一不得执行' WHERE id=1");check(!victim.value("ok",true)&&victim["error"]["code"]=="DEADLOCK","largest user ID was not deadlock victim: "+victim.dump());check(wait.wait_for(2s)==std::future_status::ready,"deadlock victim not compensated before waiter release");auto resumed=wait.get();check(resumed.value("ok",false),"survivor failed after victim rollback");sql(db,a,"COMMIT");sql(db,b,"ROLLBACK");check(rows(db,a)==json::array({json::array({1,"甲一"}),json::array({2,"甲二"})}),"victim undo overwrote survivor commit");checks.push_back({{"case","real_two_session_deadlock_victim_inverse_precedes_held_key_release"},{"status","PASS"},{"actual_wait_barrier",barrier}});}
 {auto dir=root/"boundary";seed(dir);Engine db(dir.u8string(),2);auto s=db.open_session();sql(db,s,"BEGIN");for(unsigned i=0;i<64;++i)sql(db,s,"SAVEPOINT s"+std::to_string(i));auto count_limit=db.execute(s,"SAVEPOINT over");check(!count_limit.value("ok",true)&&count_limit["error"]["code"]=="SAVEPOINT_LIMIT","64-savepoint metadata bound missing");sql(db,s,"ROLLBACK");sql(db,s,"BEGIN");auto name_limit=db.execute(s,"SAVEPOINT \""+std::string(129,'n')+"\"");check(!name_limit.value("ok",true)&&name_limit["error"]["code"]=="INVALID_IDENTIFIER","SQL identifier byte bound missing: "+name_limit.dump());sql(db,s,"ROLLBACK");sql(db,s,"CREATE TABLE wide(id INTEGER PRIMARY KEY,v VARCHAR(2000))");auto row_limit=db.execute(s,"INSERT INTO wide VALUES(1,'"+std::string(1100,'x')+"')");check(!row_limit.value("ok",true)&&row_limit["error"]["code"]=="LOGICAL_ROW_LIMIT","1KiB row budget missing");check(sql(db,s,"SELECT COUNT(*) FROM wide")["rows"][0][0]==0,"rejected wide row was written");for(unsigned i=3;i<=128;++i)sql(db,s,"INSERT INTO t VALUES("+std::to_string(i)+",'r"+std::to_string(i)+"')");auto a=db.open_session(),b=db.open_session();sql(db,a,"BEGIN");sql(db,a,"DELETE FROM t WHERE id=1");auto reserved=db.execute(b,"INSERT INTO t VALUES(129,'不得占用撤销槽')");check(!reserved.value("ok",true)&&reserved["error"]["code"]=="LOGICAL_ROW_LIMIT","other writer consumed DELETE inverse's capacity");sql(db,a,"ROLLBACK");check(sql(db,s,"SELECT COUNT(*) FROM t")["rows"][0][0]==128&&sql(db,s,"VERIFY")["verification"]["ok"],"DELETE inverse failed at128-row capacity");std::vector<std::string> readers;for(unsigned i=0;i<64;++i){auto reader=db.open_session();sql(db,reader,"BEGIN");readers.push_back(reader);}auto extra=db.open_session();auto tx_limit=db.execute(extra,"BEGIN");check(!tx_limit.value("ok",true)&&tx_limit["error"]["code"]=="LOGICAL_TX_LIMIT","64 active logical transactions not bounded");auto diagnostic=db.diagnostics();check(diagnostic["storage"]["transaction_table"].size()==64,"failed logical registration leaked a physical context");for(const auto& reader:readers)sql(db,reader,"ROLLBACK");check(!db.diagnostics()["storage"]["recovery_required"].get<bool>(),"bounded prewrite errors poisoned storage");checks.push_back({{"case","row_SAVEPOINT_context_bounds_and_DELETE_inverse_capacity_reservation"},{"status","PASS"}});}
 {auto dir=root/"coarse-read";seed(dir);Engine db(dir.u8string(),2);auto a=db.open_session(),b=db.open_session();sql(db,a,"BEGIN");sql(db,a,"INSERT INTO t VALUES(3,'外层尚未提交')");auto names=sql(db,b,"SHOW TABLES");check(names["columns"].size()==1&&names["columns"][0]["name"]=="table_name","SHOW TABLES exposed physical pending row counts");auto cache=db.diagnostics();check(cache["table_cache_stale"],"background metadata cache called pending rows committed");for(const auto& table:cache["tables"])check(table["name"]!="t","pending table bypassed coarse-nowait cache guard");auto all=std::async(std::launch::async,[&]{return db.execute(b,"SELECT COUNT(*) FROM t");});auto full_barrier=actual_wait(db,"table:t");check(all.wait_for(0ms)==std::future_status::timeout,"full read escaped coarse S barrier");sql(db,a,"ROLLBACK");check(all.wait_for(2s)==std::future_status::ready,"full reader did not resume");auto result=all.get();check(result.value("ok",false)&&result["rows"][0][0]==2&&result["locking"]["effective"]=="TABLE","full reader saw outer-pending phantom");sql(db,a,"BEGIN");sql(db,a,"UPDATE t SET v='隐藏值' WHERE id=1");auto nonpk=std::async(std::launch::async,[&]{return db.execute(b,"SELECT id FROM t WHERE v='隐藏值'");});auto predicate_barrier=actual_wait(db,"table:t");check(nonpk.wait_for(0ms)==std::future_status::timeout,"non-PK predicate escaped coarse S protection");sql(db,a,"ROLLBACK");check(nonpk.wait_for(2s)==std::future_status::ready,"non-PK reader did not resume");auto filtered=nonpk.get();check(filtered.value("ok",false)&&filtered["rows"].empty()&&filtered["locking"]["effective"]=="TABLE","non-PK reader exposed uncommitted value");checks.push_back({{"case","full_and_nonPK_predicate_reads_use_actual_coarse_S_and_cache_omits_pending_count"},{"status","PASS"},{"full_scan_wait",full_barrier},{"predicate_wait",predicate_barrier}});}
 return {{"status","PASS"},{"checks",checks},{"scope","Real frozen Engine SQL with isolated logical journal/physical mini-transactions; not installed in apps"}};
}
void worker(const std::string& kind,const fs::path& root){Engine db(root.u8string(),2);auto a=db.open_session(),b=db.open_session();same_page(db,a,b);if(kind=="rollback")sql(db,a,"ROLLBACK");else if(kind=="commit")sql(db,a,"COMMIT");else check(kind=="loser","unknown worker kind");std::ofstream out(root/"ready.json",std::ios::binary);out<<json{{"status","READY"},{"kind",kind},{"diagnostics",db.diagnostics()}}.dump();out.close();std::cout<<"READY\n"<<std::flush;std::this_thread::sleep_for(20s);throw std::runtime_error("parent did not kill owned worker within20 seconds");}
}
int main(int argc,char** argv){try{if(argc==1){auto root=fs::temp_directory_path()/("edudb-logical-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::cout<<units(root).dump(2)<<"\n";return 0;}check(argc>=3,"usage --unit|--seed|--snapshot DIR or --worker KIND DIR");auto mode=std::string(argv[1]);if(mode=="--unit"){std::cout<<units(fs::u8path(argv[2])).dump(2)<<"\n";return 0;}if(mode=="--seed"){seed(fs::u8path(argv[2]));std::cout<<"{\"status\":\"PASS\"}\n";return 0;}if(mode=="--snapshot"){std::cout<<snapshot(fs::u8path(argv[2])).dump(2)<<"\n";return 0;}if(mode=="--worker"&&argc==4){worker(argv[2],fs::u8path(argv[3]));return 2;}throw std::runtime_error("invalid mode");}catch(const DbError& e){std::cerr<<json{{"status","ERROR"},{"code",e.code},{"message",e.what()}}.dump()<<"\n";return 4;}catch(const std::exception& e){std::cerr<<json{{"status","FAIL"},{"message",e.what()}}.dump()<<"\n";return 5;}}
